inline std::ostream& operator<<(std::ostream& os, KernelStatus s)
{
    switch (s) {
    case KernelStatus::Ok:
        return os << "ok";
    case KernelStatus::Overflow:
        return os << "overflow";
    case KernelStatus::ZeroDenominator:
        return os << "zero_denominator";
    }
    return os << "invalid";
}
